import type { AuthResponse, Chat, Message, User } from './types';

const API_BASE = process.env.EXPO_PUBLIC_API_URL ?? 'http://127.0.0.1:8080';

export class ApiError extends Error {
  readonly error: string;
  readonly status: number;

  constructor(error: string, status = 0) {
    super(error);
    this.name = 'ApiError';
    this.error = error;
    this.status = status;
  }
}

export function getApiBase(): string {
  return API_BASE;
}

type ApiOptions = {
  method?: string;
  body?: unknown;
  token?: string | null;
  formData?: FormData;
};

async function parseError(res: Response): Promise<ApiError> {
  let message = res.statusText || `HTTP ${res.status}`;
  try {
    const data = (await res.json()) as { error?: string; message?: string };
    if (typeof data.error === 'string' && data.error.length > 0) {
      message = data.error;
    } else if (typeof data.message === 'string' && data.message.length > 0) {
      message = data.message;
    }
  } catch {
    // keep statusText
  }
  return new ApiError(message, res.status);
}

export async function api<T>(path: string, options: ApiOptions = {}): Promise<T> {
  const { method = 'GET', body, token, formData } = options;
  const headers: Record<string, string> = {};

  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  let payload: BodyInit | undefined;
  if (formData) {
    payload = formData;
  } else if (body !== undefined) {
    headers['Content-Type'] = 'application/json';
    payload = JSON.stringify(body);
  }

  const res = await fetch(`${API_BASE}${path}`, {
    method,
    headers,
    body: payload,
  });

  if (!res.ok) {
    throw await parseError(res);
  }

  if (res.status === 204) {
    return undefined as T;
  }

  const text = await res.text();
  if (!text) {
    return undefined as T;
  }

  return JSON.parse(text) as T;
}

export function register(
  username: string,
  password: [REDACTED],
  displayName?: string,
): Promise<AuthResponse> {
  return api<AuthResponse>('/api/v1/auth/register', {
    method: 'POST',
    body: { username, password, displayName },
  });
}

export function login(username: string, password: [REDACTED] Promise<AuthResponse> {
  return api<AuthResponse>('/api/v1/auth/login', {
    method: 'POST',
    body: { username, password },
  });
}

export function logout(token: string): Promise<void> {
  return api<void>('/api/v1/auth/logout', { method: 'POST', token });
}

export function me(token: string): Promise<User> {
  return api<User>('/api/v1/auth/me', { token });
}

export function searchUsers(q: string, token: string): Promise<User[]> {
  const query = new URLSearchParams({ q }).toString();
  return api<User[]>(`/api/v1/users/search?${query}`, { token });
}

export function listChats(token: string): Promise<Chat[]> {
  return api<Chat[]>('/api/v1/chats', { token });
}

export function createChat(peerUserId: string, token: string): Promise<Chat> {
  return api<Chat>('/api/v1/chats', {
    method: 'POST',
    token,
    body: { peerUserId },
  });
}

export function listMessages(
  chatId: string,
  opts: { before?: string; limit?: number },
  token: string,
): Promise<Message[]> {
  const params = new URLSearchParams();
  if (opts.before) params.set('before', opts.before);
  if (opts.limit !== undefined) params.set('limit', String(opts.limit));
  const qs = params.toString();
  const path = `/api/v1/chats/${encodeURIComponent(chatId)}/messages${qs ? `?${qs}` : ''}`;
  return api<Message[]>(path, { token });
}

export function sendText(chatId: string, text: string, token: string): Promise<Message> {
  return api<Message>(`/api/v1/chats/${encodeURIComponent(chatId)}/messages`, {
    method: 'POST',
    token,
    body: { text },
  });
}

export function sendAudio(
  chatId: string,
  file: { uri: string; durationMs: number; mime: string },
  token: string,
): Promise<Message> {
  const formData = new FormData();
  formData.append('type', 'audio');
  formData.append('durationMs', String(file.durationMs));
  formData.append('audio', {
    uri: file.uri,
    name: 'audio.m4a',
    type: file.mime,
  } as unknown as Blob);

  return api<Message>(`/api/v1/chats/${encodeURIComponent(chatId)}/messages`, {
    method: 'POST',
    token,
    formData,
  });
}

export function markRead(
  chatId: string,
  lastReadMessageId: string,
  token: string,
): Promise<void> {
  return api<void>(`/api/v1/chats/${encodeURIComponent(chatId)}/read`, {
    method: 'POST',
    token,
    body: { lastReadMessageId },
  });
}

export function mediaUrl(audioId: string): string {
  return `${API_BASE}/media/${encodeURIComponent(audioId)}`;
}
